274:   const name = nameCreature(org.genome);
275:   const color = creatureColorHex(creature);
276:   els.panel.style.setProperty("--specimen-color", color);
277:   els.specimenGlyph.style.setProperty("--specimen-color", color);
278:   const hslColor = new THREE.Color(color);
279:   const hsl = {};
280:   hslColor.getHSL(hsl);
281:   els.specimenLatin.style.color = `hsl(${Math.round(hsl.h * 360)}, 28%, 58%)`;
282: 
283:   els.specimenId.textContent = `SPECIMEN K-${pad(creatures.selectedIndex + 1)}`;
284:   els.specimenName.textContent = name.common;
285:   els.specimenLatin.textContent = name.latin;
