432:   buildPond() {
433:     const group = new THREE.Group();
434:     this.root.add(group);
435:     this.pondGroup = group;
436: 
437:     const shore = new THREE.Mesh(
438:       new THREE.RingGeometry(POND.radius * 0.92, POND.radius * 1.33, 56),
439:       new THREE.MeshStandardMaterial({ color: 0x6a6b4e, roughness: 0.98, side: THREE.DoubleSide }),
440:     );
441:     shore.rotation.x = -Math.PI / 2;
442:     shore.scale.set(1.2, 1, 0.82);
443:     shore.position.set(POND.x, 0.022, POND.z);
444:     shore.receiveShadow = true;
445:     group.add(shore);
446: 
447:     const waterMat = new THREE.MeshPhysicalMaterial({
448:       color: 0x0a4650,
449:       roughness: 0.14,
450:       metalness: 0.05,
451:       transmission: 0.16,
452:       transparent: true,
453:       opacity: 0.88,
454:       clearcoat: 1,
455:       clearcoatRoughness: 0.12,
456:       envMapIntensity: 0.4,
457:       side: THREE.DoubleSide,
458:     });
459:     const water = new THREE.Mesh(new THREE.CircleGeometry(POND.radius * 0.94, 64), waterMat);
460:     water.rotation.x = -Math.PI / 2;
461:     water.scale.set(1.18, 0.8, 1);
462:     water.position.set(POND.x, 0.075, POND.z);
463:     water.receiveShadow = true;
464:     group.add(water);
465:     this.water = water;
466: 
467:     for (let i = 0; i < 3; i += 1) {
468:       const ripple = new THREE.Mesh(
469:         new THREE.RingGeometry(0.35 + i * 0.33, 0.37 + i * 0.33, 64),
470:         new THREE.MeshBasicMaterial({ color: 0xa7ffe2, transparent: true, opacity: 0.2, side: THREE.DoubleSide }),
471:       );
472:       ripple.rotation.x = -Math.PI / 2;
473:       ripple.scale.set(1.2, 0.82, 1);
474:       ripple.position.set(POND.x - 0.25, 0.087, POND.z + 0.15);
475:       group.add(ripple);
476:       this.ripples.push({ mesh: ripple, offset: i * 0.95 });
