668:   buildMushrooms(group, rng) {
669:     const stemMat = new THREE.MeshStandardMaterial({ color: 0xa5bca1, roughness: 0.8 });
670:     const capMats = [
671:       new THREE.MeshStandardMaterial({
672:         color: 0xb2ffcc,
673:         emissive: 0x63ffc0,
674:         emissiveIntensity: 0.4,
675:         roughness: 0.4,
676:       }),
677:       new THREE.MeshStandardMaterial({
678:         color: 0x7ce8ff,
679:         emissive: 0x38cfff,
680:         emissiveIntensity: 0.5,
681:         roughness: 0.35,
682:       }),
683:     ];
684:     const sites = [
685:       [-5.2, -3.5],
686:       [4.7, -4.9],
687:       [-1.6, -4.4],
688:       [2.7, -4.8],
689:       [6.4, -2.6],
690:     ];
691:     sites.forEach(([sx, sz], s) => {
692:       const cluster = new THREE.Group();
693:       cluster.position.set(sx, terrainHeight(sx, sz), sz);
694:       for (let i = 0; i < 3 + (s % 3); i += 1) {
695:         const h = 0.25 + rng() * 0.4;
696:         const stem = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.026, h, 5), stemMat);
