404:   buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
405:     const g = this.genome;
406:     const upperLen = legLen * 0.55;
407:     const lowerLen = legLen * 0.48;
408:     const legRadius = 0.058 + g.bodySize * 0.032;
409:     const positions = [
410:       { x: -bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: 0 },
411:       { x: bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: Math.PI },
412:       { x: -bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: Math.PI },
413:       { x: bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: 0 },
414:     ];
415: 
416:     positions.forEach((entry, i) => {
417:       const root = new THREE.Group();
418:       root.position.set(entry.x, bodyY - bodyH * 0.26, entry.z);
419:       this.model.add(root);
420: 
421:       const shoulder = new THREE.Mesh(this.torsoGeo, this.limbMat);
422:       shoulder.scale.set(legRadius * 1.22, legRadius * 1.25, legRadius * 1.3);
423:       root.add(shoulder);
424: 
425:       const thigh = new THREE.Mesh(this.torsoGeo, this.limbMat);
426:       thigh.scale.set(legRadius * 1.35, upperLen * 0.32, legRadius * 1.35);
427:       thigh.position.y = -upperLen * 0.36;
428:       thigh.castShadow = true;
429:       root.add(thigh);
430: 
431:       const upper = new THREE.Mesh(
432:         new THREE.CylinderGeometry(legRadius * 0.82, legRadius * 0.68, upperLen, 8),
433:         this.limbMat,
434:       );
435:       upper.position.y = -upperLen / 2;
436:       upper.castShadow = true;
437:       root.add(upper);
438: 
439:       const knee = new THREE.Group();
440:       knee.position.y = -upperLen;
441:       root.add(knee);
442: 
443:       const kneeJoint = new THREE.Mesh(this.torsoGeo, this.limbMat);
444:       kneeJoint.scale.setScalar(legRadius * 0.8);
445:       knee.add(kneeJoint);
446: 
447:       const lower = new THREE.Mesh(
448:         new THREE.CylinderGeometry(legRadius * 0.68, legRadius * 0.5, lowerLen, 7),
449:         this.limbMat,
450:       );
451:       lower.position.y = -lowerLen / 2;
452:       lower.castShadow = true;
453:       knee.add(lower);
454: 
455:       const foot = new THREE.Mesh(this.torsoGeo, this.limbMat);
456:       foot.scale.set(legRadius * 1.65, legRadius * 0.58, legRadius * 2.25);
457:       foot.position.set(0, -lowerLen - legRadius * 0.17, legRadius * 0.7);
458:       foot.castShadow = true;
459:       knee.add(foot);
460: 
461:       for (let toe = -1; toe <= 1; toe += 1) {
462:         const claw = new THREE.Mesh(new THREE.ConeGeometry(legRadius * 0.17, legRadius * 0.75, 4), this.darkBoneMat);
463:         claw.position.set(toe * legRadius * 0.62, -lowerLen + legRadius * 0.02, legRadius * 1.9);
464:         claw.rotation.x = Math.PI / 2.4;
465:         knee.add(claw);
466:       }
467: 
468:       this.legs.push({
469:         root,
470:         knee,
471:         phase: entry.phase,
472:         front: entry.front,
473:         upperLen,
474:         lowerLen,
475:         baseRot: entry.front ? 0.05 : -0.04,
476:       });
477:     });
