556: function directMutation(gene = null) {
557:   if (state.transitioning) return;
558:   hideHint();
559:   const org = currentOrganism();
560:   const creature = creatures.selected;
561:   if (!org || !creature) return;
562:   if (state.mutagen <= 0) {
563:     showToast("Mutagen reserve depleted", "Advance a generation to replenish the reserve", "!", 3000);
564:     audio.error();
565:     return;
566:   }
567: 
568:   const key = gene || TRAIT_ROWS[Math.floor(random() * TRAIT_ROWS.length)];
569:   const result = mutateGene(org.genome, key, random, 0.17);
570:   org.genome = result.genome;
571:   org.evaluation = evaluate(org.genome, state.env, org.condition);
572:   org.changes = result.changes;
573:   state.mutagen -= 1;
574:   creatures.replace(creatures.selectedIndex, org);
575:   const mutated = creatures.selected;
576:   world.burst(mutated.position, mutated.accentColor ?? 0xcaff72, 0.75);
577: 
578:   const change = result.changes[0];
579:   const info = describeChange(change);
580:   showToast(info.title, `${info.detail} · directed mutation expressed`, "⌁", 3300);
581:   addLog(`Directed mutation: <b>${info.title}</b> in specimen K-${pad(creatures.selectedIndex + 1)}.`, true);
582:   if (state.history.length) state.history[state.history.length - 1] = meanFitness();
583:   updateAll();
584:   audio.mutate();
585: }
