368:   buildTail({ bodyLen, bodyH, bodyY, tailLen }) {
369:     const g = this.genome;
370:     const base = new THREE.Group();
371:     base.position.set(0, bodyY + 0.01, -bodyLen * 0.77);
372:     base.rotation.x = -0.13;
373:     this.model.add(base);
374:     this.tailJoints.push(base);
375: 
376:     let parent = base;
377:     const segments = 5;
378:     const segLen = tailLen / segments;
379:     for (let i = 0; i < segments; i += 1) {
380:       const joint = new THREE.Group();
381:       joint.position.z = i === 0 ? 0 : -segLen;
382:       joint.rotation.x = i === 0 ? 0 : 0.035;
383:       parent.add(joint);
384:       const taper = 1 - (i / segments) * 0.82;
385:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
386:       segment.scale.set(0.115 * taper, 0.105 * taper, segLen * 0.72);
387:       segment.position.z = -segLen * 0.5;
388:       segment.castShadow = true;
389:       joint.add(segment);
390:       this.tailJoints.push(joint);
391:       parent = joint;
392:     }
393: 
394:     if (g.armor > 0.58) {
395:       const club = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12 + g.armor * 0.1, 0), this.boneMat);
396:       club.position.z = -segLen * 0.92;
397:       club.scale.set(1.2, 0.85, 1.35);
398:       club.rotation.set(0.2, 0.4, 0.1);
399:       club.castShadow = true;
400:       parent.add(club);
401:     }
402:   }
