653: export class CreatureSystem {
654:   constructor(world) {
655:     this.world = world;
656:     this.creatures = [];
657:     this.selectedIndex = 0;
658:     this.rand = mulberry32(911);
659:     this.raycaster = new THREE.Raycaster();
660:     this.pointer = new THREE.Vector2();
661:   }
662: 
663:   spawnPopulation(population, positions) {
664:     for (const creature of this.creatures) {
665:       creature.dispose();
666:     }
667:     this.creatures = [];
668:     population.forEach((organism, index) => {
669:       const creature = new Creature({
670:         genome: organism.genome,
671:         evaluation: organism.evaluation,
672:         world: this.world,
673:         rng: mulberry32(3001 + index * 137 + organism.id * 13),
674:         index,
675:         position: positions[index],
676:       });
677:       organism.creature = creature;
678:       this.creatures.push(creature);
679:     });
680:     this.selectedIndex = Math.min(this.selectedIndex, this.creatures.length - 1);
681:     this.select(this.selectedIndex, true);
682:   }
683: 
684:   select(index, updateFocus = true) {
685:     this.selectedIndex = Math.max(0, Math.min(this.creatures.length - 1, index));
686:     const creature = this.creatures[this.selectedIndex];
687:     if (!creature) return null;
688:     if (updateFocus) {
689:       this.world.setSelection(creature.position, creature.radius);
690:     }
691:     return creature;
692:   }
693: 
694:   replace(index, organism) {
695:     const old = this.creatures[index];
696:     if (!old) return null;
697:     const position = old.position.clone();
698:     const wasSelected = this.selectedIndex === index;
699:     old.dispose();
700:     const creature = new Creature({
701:       genome: organism.genome,
702:       evaluation: organism.evaluation,
703:       world: this.world,
704:       rng: mulberry32(7103 + index * 193 + organism.id * 7),
705:       index,
706:       position,
707:     });
708:     organism.creature = creature;
709:     this.creatures[index] = creature;
710:     if (wasSelected) this.select(index);
