819:     creature.position.z,
820:   );
821:   tagWorld.project(world.camera);
822:   if (tagWorld.z > 1 || tagWorld.z < -1) {
823:     els.creatureTag.style.opacity = "0";
824:     return;
825:   }
826:   const x = (tagWorld.x * 0.5 + 0.5) * window.innerWidth;
827:   const y = (-tagWorld.y * 0.5 + 0.5) * window.innerHeight;
828:   const covered = window.innerWidth > 900 && (x < 345 || x > window.innerWidth - 345);
829:   els.creatureTag.style.opacity = covered ? "0" : "1";
830:   els.creatureTag.style.left = `${x}px`;
831:   els.creatureTag.style.top = `${y}px`;
832: }
