242:   const suffix = candidates[0].score > 0.58 ? candidates[0].name : "Walker";
243: 
244:   let genus = "Aurelia";
245:   if (genome.armor > 0.62) genus = "Thoracis";
246:   else if (genome.neck > 0.68) genus = "Longicollis";
247:   else if (genome.legs > 0.7) genus = "Cursor";
248:   else if (genome.bodySize > 0.72) genus = "Titanus";
249:   else if (genome.speed > 0.72) genus = "Velox";
250:   else if (genome.bodySize < 0.3) genus = "Pygmaeus";
251: 
252:   const hueName = hue < 70 ? "flavus" : hue < 95 ? "viridis" : hue < 125 ? "prasinus" : "caeruleus";
253: 
254:   return {
255:     common: `${prefix} ${suffix}`,
256:     latin: `${genus} ${hueName}`,
257:   };
258: }
