339: export function pressureOutlook(env) {
340:   if (env.climate === 0 && env.food === 0) {
341:     return "Cold and hunger together reward compact, well-insulated bodies with reach. Efficiency is everything.";
342:   }
343:   if (env.climate === 2 && env.food === 0) {
344:     return "Heat and scarcity favor long limbs, light bodies, and low metabolic waste. Small survivors win.";
345:   }
346:   if (env.predators === 2) {
347:     return "Rampant predation makes armor and acceleration decisive. Display structures become liabilities.";
348:   }
349:   if (env.food === 0) {
350:     return "Sparse forage rewards longer necks and longer strides. Heavy bodies must work harder for every calorie.";
351:   }
352:   if (env.climate === 0) {
353:     return "Frigid nights favor bulk and insulation. Long, exposed limbs leak precious heat.";
354:   }
355:   if (env.climate === 2) {
356:     return "Arid air favors small bodies and long limbs that shed heat. Insulation becomes a burden.";
357:   }
358:   if (env.food === 2) {
359:     return "Lush growth supports larger bodies. Competition shifts from reach toward display and defense.";
360:   }
361:   if (env.predators === 0) {
362:     return "Without predators, costly armor and sprinting fade. Selection favors efficient foragers.";
363:   }
364:   return "Stable temperatures reward generalists. Predators favor speed and armor.";
365: }

