47:     ctx.fillStyle = rng() > 0.42
48:       ? `hsla(${hue - 8 - rng() * 18}, ${saturation + 10}%, ${lightness - 13 - rng() * 12}%, ${0.25 + rng() * 0.38})`
49:       : `hsla(${hue + 9}, ${saturation + 2}%, ${lightness + 12}%, ${0.14 + rng() * 0.22})`;
50:     ctx.beginPath();
51:     ctx.ellipse(x, y, rx, ry, rng() * Math.PI, 0, Math.PI * 2);
52:     ctx.fill();
53:   }
54: 
55:   if (genome.pattern > 0.34) {
56:     const stripes = 4 + Math.floor(genome.pattern * 7);
57:     ctx.globalAlpha = 0.13 + genome.pattern * 0.2;
58:     ctx.strokeStyle = hsl(hue - 12, saturation + 14, lightness - 20);
59:     ctx.lineWidth = 3 + genome.pattern * 7;
60:     for (let i = 0; i < stripes; i += 1) {
61:       const x = (i / stripes) * size + rng() * 10;
62:       ctx.beginPath();
63:       ctx.moveTo(x, -10);
64:       ctx.bezierCurveTo(x + 15, size * 0.3, x - 18, size * 0.7, x + 8, size + 10);
65:       ctx.stroke();
66:     }
67:     ctx.globalAlpha = 1;
68:   }
69: 
70:   // Fine dermal speckle.
71:   for (let i = 0; i < 1200; i += 1) {
72:     const x = rng() * size;
73:     const y = rng() * size;
74:     ctx.fillStyle = `rgba(20, 34, 26, ${0.025 + rng() * 0.09})`;
75:     ctx.fillRect(x, y, 0.8 + rng() * 1.6, 0.8 + rng() * 1.6);
76:   }
77: 
78:   const texture = new THREE.CanvasTexture(canvas);
79:   texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
80:   texture.colorSpace = THREE.SRGBColorSpace;
81:   texture.anisotropy = 4;
82:   return { texture, hue, saturation, lightness };
83: }
84: 
85: function makeCrestGeometry() {
86:   const shape = new THREE.Shape();
87:   shape.moveTo(0, 0);
88:   shape.bezierCurveTo(0.28, 0.02, 0.36, 0.3, 0.18, 0.48);
89:   shape.bezierCurveTo(0.09, 0.57, 0.01, 0.46, -0.04, 0.31);
90:   shape.bezierCurveTo(-0.05, 0.18, -0.06, 0.06, 0, 0);
91:   return new THREE.ShapeGeometry(shape, 10);
92: }
