94: export class Creature {
95:   constructor({ genome, evaluation, world, rng, index, position }) {
96:     this.genome = genome;
97:     this.evaluation = evaluation;
98:     this.world = world;
99:     this.rng = rng;
100:     this.index = index;
101:     this.nameData = nameCreature(genome);
102:     this.spawnTime = world.time;
103:     this.group = new THREE.Group();
104:     this.group.userData.creature = this;
105:     this.group.userData.creatureId = index;
106:     this.model = new THREE.Group();
107:     this.group.add(this.model);
108:     this.world.addLifeObject(this.group);
109: 
110:     this.position = new THREE.Vector3(position.x, terrainHeight(position.x, position.z), position.z);
111:     this.home = this.position.clone();
112:     this.group.position.copy(this.position);
113:     this.heading = rng() * TAU;
114:     this.group.rotation.y = this.heading;
115:     this.target = this.position.clone();
116:     this.walkPhase = rng() * TAU;
117:     this.blinkPhase = rng() * 8;
118:     this.moving = false;
119:     this.selected = false;
120:     this.dimensions = {};
121:     this.movementSpeed = 0.8;
122:     this.legs = [];
123:     this.tailJoints = [];
124:     this.eyes = [];
125:     this.crestMeshes = [];
126:     this.tempTarget = new THREE.Vector3();
127: 
128:     this.build();
129:     this.chooseTarget(true);
130:     if (index === 0) {
131:       this.heading = Math.atan2(
132:         world.camera.position.x - this.position.x,
133:         world.camera.position.z - this.position.z,
134:       );
135:       this.group.rotation.y = this.heading;
136:       this.target.set(
137:         this.position.x + Math.sin(this.heading) * 1.2,
138:         this.position.y,
139:         this.position.z + Math.cos(this.heading) * 1.2,
140:       );
141:     }
142:   }
143: 
144:   get radius() {
145:     return (0.58 + this.genome.bodySize * 0.42) * (0.82 + this.genome.bodySize * 0.5);
146:   }
147: 
148:   build() {
149:     const g = this.genome;
150:     const rng = this.rng;
151:     const sizeScale = 0.82 + g.bodySize * 0.55;
152:     this.sizeScale = sizeScale;
153:     this.model.scale.setScalar(0.01);
154:     this.spawnTime = this.world.time;
155: 
156:     const skin = makeSkinTexture(g, this.index + 3);
157:     this.skinTexture = skin.texture;
158:     const hue = skin.hue;
159:     const baseColor = new THREE.Color().setHSL(hue / 360, skin.saturation / 100, skin.lightness / 100, THREE.SRGBColorSpace);
160:     const accentColor = new THREE.Color().setHSL(((hue + 48) % 360) / 360, 0.46, 0.36, THREE.SRGBColorSpace);
161:     const bellyColor = new THREE.Color().setHSL(((hue + 14) % 360) / 360, 0.22, 0.57, THREE.SRGBColorSpace);
162:     const limbColor = new THREE.Color().setHSL(((hue - 2) % 360) / 360, 0.3, 0.28, THREE.SRGBColorSpace);
163:     this.themeColor = baseColor;
164:     this.accentColor = accentColor;
165: 
166:     this.bodyMat = new THREE.MeshStandardMaterial({
167:       map: skin.texture,
168:       bumpMap: skin.texture,
169:       bumpScale: 0.012,
170:       roughness: 0.76,
171:       metalness: 0.015,
172:       color: 0xffffff,
173:     });
174:     this.limbMat = new THREE.MeshStandardMaterial({
175:       color: limbColor,
176:       roughness: 0.83,
177:       metalness: 0.01,
178:     });
179:     this.bellyMat = new THREE.MeshStandardMaterial({ color: bellyColor, roughness: 0.86 });
180:     this.boneMat = new THREE.MeshStandardMaterial({ color: 0xaaa48d, roughness: 0.7, metalness: 0.03 });
181:     this.darkBoneMat = new THREE.MeshStandardMaterial({ color: 0x6e6858, roughness: 0.84 });
182:     this.eyeMat = new THREE.MeshStandardMaterial({ color: 0x090d0a, roughness: 0.17, metalness: 0.12 });
183:     this.glintMat = new THREE.MeshBasicMaterial({ color: 0xd9ffed });
184:     this.crestMat = new THREE.MeshStandardMaterial({
185:       color: accentColor,
186:       emissive: accentColor,
187:       emissiveIntensity: 0.08,
188:       roughness: 0.78,
189:       transparent: true,
190:       opacity: 0.82,
191:       side: THREE.DoubleSide,
192:     });
193:     this.accentMat = new THREE.MeshStandardMaterial({
194:       color: accentColor,
195:       emissive: accentColor,
196:       emissiveIntensity: 0.16,
197:       roughness: 0.6,
198:       transparent: true,
199:       opacity: 0.8,
200:       side: THREE.DoubleSide,
201:     });
202:     this.spotMat = new THREE.MeshStandardMaterial({
203:       color: accentColor,
204:       emissive: accentColor,
205:       emissiveIntensity: 0.3,
206:       roughness: 0.45,
207:       transparent: true,
208:       opacity: 0.6,
209:     });
210: 
211:     // Proportions: raw genes become an actual biological body plan.
212:     const bodyLen = 0.9;
213:     const bodyW = 0.29 + g.fat * 0.1;
214:     const bodyH = 0.32 + g.fat * 0.11;
215:     const legLen = 0.53 + g.legs * 0.8;
216:     const neckLen = 0.15 + g.neck * 0.9;
217:     const tailLen = 0.24 + g.tail * 1.02;
218:     const bodyY = legLen + bodyH * 0.26 + 0.03;
219:     this.dimensions = { bodyLen, bodyW, bodyH, legLen, neckLen, tailLen, bodyY };
220:     this.bodyY = bodyY;
221: 
222:     const sphereGeo = new THREE.SphereGeometry(1, 24, 18);
223:     this.torsoGeo = sphereGeo;
224: 
225:     const torso = new THREE.Mesh(sphereGeo, this.bodyMat);
226:     torso.scale.set(bodyW, bodyH, bodyLen);
227:     torso.position.y = bodyY;
228:     torso.castShadow = true;
229:     torso.receiveShadow = true;
230:     this.model.add(torso);
231:     this.torso = torso;
232: 
233:     const chest = new THREE.Mesh(sphereGeo, this.bodyMat);
234:     chest.scale.set(bodyW * 0.93, bodyH * 0.9, bodyLen * 0.56);
235:     chest.position.set(0, bodyY + 0.015, bodyLen * 0.58);
236:     chest.castShadow = true;
237:     this.model.add(chest);
238: 
239:     const hip = new THREE.Mesh(sphereGeo, this.bodyMat);
240:     hip.scale.set(bodyW * 0.86, bodyH * 0.84, bodyLen * 0.5);
241:     hip.position.set(0, bodyY + 0.005, -bodyLen * 0.58);
242:     hip.castShadow = true;
243:     this.model.add(hip);
244: 
245:     const belly = new THREE.Mesh(sphereGeo, this.bellyMat);
246:     belly.scale.set(bodyW * 0.8, bodyH * 0.42, bodyLen * 0.86);
247:     belly.position.set(0, bodyY - bodyH * 0.38, bodyLen * 0.06);
248:     this.model.add(belly);
249: 
250:     this.buildNeck({ bodyLen, bodyW, bodyH, bodyY, neckLen, accentColor });
251:     this.buildTail({ bodyLen, bodyH, bodyY, tailLen });
252:     this.buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen });
253:     this.buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen });
254:     this.buildAccents({ bodyLen, bodyW, bodyH, bodyY });
255:   }
256: 
257:   buildNeck({ bodyLen, bodyW, bodyH, bodyY, neckLen, accentColor }) {
258:     const g = this.genome;
259:     const neckGroup = new THREE.Group();
260:     neckGroup.position.set(0, bodyY + bodyH * 0.3, bodyLen * 0.69);
261:     neckGroup.rotation.x = 0.62 + g.neck * 0.2;
262:     this.model.add(neckGroup);
263:     this.neckGroup = neckGroup;
264: 
265:     const segCount = 4;
266:     for (let i = 0; i < segCount; i += 1) {
267:       const t = (i + 0.5) / segCount;
268:       const taper = 1 - t * 0.22;
269:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
270:       const segLen = neckLen / segCount;
271:       segment.scale.set(
272:         (0.14 + g.neck * 0.022) * taper,
273:         segLen * 0.68,
274:         (0.135 + g.neck * 0.02) * taper,
275:       );
276:       segment.position.set(0, t * neckLen, Math.sin(t * Math.PI) * 0.035);
277:       segment.castShadow = true;
278:       neckGroup.add(segment);
279:     }
280: 
281:     const headGroup = new THREE.Group();
282:     headGroup.position.set(0, neckLen + 0.045, 0.085);
283:     headGroup.rotation.x = -0.54;
284:     neckGroup.add(headGroup);
285:     this.headGroup = headGroup;
286: 
287:     const headR = 0.205 + g.crest * 0.026;
288:     const cranium = new THREE.Mesh(this.torsoGeo, this.bodyMat);
289:     cranium.scale.set(headR * 1.02, headR * 0.9, headR * 1.28);
290:     cranium.castShadow = true;
291:     headGroup.add(cranium);
292: 
293:     const snout = new THREE.Mesh(this.torsoGeo, this.bodyMat);
294:     snout.scale.set(headR * 0.72, headR * 0.5, headR * 1.05);
295:     snout.position.set(0, -headR * 0.17, headR * 1.48);
296:     snout.castShadow = true;
297:     headGroup.add(snout);
298: 
299:     const jaw = new THREE.Mesh(this.torsoGeo, this.bellyMat);
300:     jaw.scale.set(headR * 0.62, headR * 0.24, headR * 0.88);
301:     jaw.position.set(0, -headR * 0.55, headR * 1.36);
302:     headGroup.add(jaw);
303: 
304:     const browRidge = new THREE.Mesh(this.torsoGeo, this.limbMat);
305:     browRidge.scale.set(headR * 0.84, headR * 0.18, headR * 0.52);
306:     browRidge.position.set(0, headR * 0.5, headR * 0.36);
307:     headGroup.add(browRidge);
308: 
309:     for (const side of [-1, 1]) {
310:       const eyeSocket = new THREE.Mesh(this.torsoGeo, this.bellyMat);
311:       eyeSocket.scale.set(headR * 0.35, headR * 0.3, headR * 0.32);
312:       eyeSocket.position.set(side * headR * 0.78, headR * 0.25, headR * 0.62);
313:       headGroup.add(eyeSocket);
314: 
315:       const eye = new THREE.Mesh(this.torsoGeo, this.eyeMat);
316:       eye.scale.setScalar(headR * 0.22);
317:       eye.position.set(side * headR * 0.89, headR * 0.28, headR * 0.72);
318:       eye.userData.baseScaleY = headR * 0.22;
319:       headGroup.add(eye);
320:       this.eyes.push(eye);
321: 
322:       const glint = new THREE.Mesh(new THREE.SphereGeometry(1, 7, 5), this.glintMat);
323:       glint.scale.setScalar(headR * 0.055);
324:       glint.position.set(side * headR * 0.94, headR * 0.34, headR * 0.86);
325:       headGroup.add(glint);
326: 
327:       if (g.armor > 0.42) {
328:         const brow = new THREE.Mesh(new THREE.ConeGeometry(headR * 0.14, headR * (0.26 + g.armor * 0.4), 4), this.boneMat);
329:         brow.position.set(side * headR * 0.74, headR * 0.58, headR * 0.46);
330:         brow.rotation.set(-0.4, 0, side * -0.4);
331:         brow.castShadow = true;
332:         headGroup.add(brow);
333:       }
334:     }
335: 
336:     const nostrilGeo = new THREE.SphereGeometry(headR * 0.05, 6, 4);
337:     for (const side of [-1, 1]) {
338:       const nostril = new THREE.Mesh(nostrilGeo, this.eyeMat);
339:       nostril.position.set(side * headR * 0.18, -headR * 0.02, headR * 1.86);
340:       headGroup.add(nostril);
341:     }
342: 
343:     if (g.crest > 0.18) {
344:       const crest = new THREE.Mesh(makeCrestGeometry(), this.crestMat);
345:       crest.scale.set(0.46 + g.crest * 0.55, 0.32 + g.crest * 0.5, 1);
346:       crest.position.set(0, headR * 0.28, -headR * 0.12);
347:       crest.rotation.set(0.18, Math.PI / 2, 0.02);
348:       crest.castShadow = true;
349:       headGroup.add(crest);
350:       this.crestMeshes.push(crest);
351: 
352:       const crestBrother = crest.clone();
353:       crestBrother.position.x = 0.008;
354:       headGroup.add(crestBrother);
355:     }
356: 
357:     // Neck frill when display alleles are strong.
358:     if (g.crest > 0.64) {
359:       for (const side of [-1, 1]) {
360:         const frill = new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.16, 4), this.accentMat);
361:         frill.position.set(side * 0.095, neckLen * 0.72, 0);
362:         frill.rotation.z = side * 1.15;
363:         neckGroup.add(frill);
364:       }
365:     }
366:   }
367: 
368:   buildTail({ bodyLen, bodyH, bodyY, tailLen }) {
369:     const g = this.genome;
370:     const base = new THREE.Group();
371:     base.position.set(0, bodyY + 0.01, -bodyLen * 0.77);
372:     base.rotation.x = -0.13;
373:     this.model.add(base);
374:     this.tailJoints.push(base);
375: 
376:     let parent = base;
377:     const segments = 5;
378:     const segLen = tailLen / segments;
379:     for (let i = 0; i < segments; i += 1) {
380:       const joint = new THREE.Group();
381:       joint.position.z = i === 0 ? 0 : -segLen;
382:       joint.rotation.x = i === 0 ? 0 : 0.035;
383:       parent.add(joint);
384:       const taper = 1 - (i / segments) * 0.82;
385:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
386:       segment.scale.set(0.115 * taper, 0.105 * taper, segLen * 0.72);
387:       segment.position.z = -segLen * 0.5;
388:       segment.castShadow = true;
389:       joint.add(segment);
390:       this.tailJoints.push(joint);
391:       parent = joint;
392:     }
393: 
394:     if (g.armor > 0.58) {
395:       const club = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12 + g.armor * 0.1, 0), this.boneMat);
396:       club.position.z = -segLen * 0.92;
397:       club.scale.set(1.2, 0.85, 1.35);
398:       club.rotation.set(0.2, 0.4, 0.1);
399:       club.castShadow = true;
400:       parent.add(club);
401:     }
402:   }
403: 
404:   buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
405:     const g = this.genome;
406:     const upperLen = legLen * 0.55;
407:     const lowerLen = legLen * 0.48;
408:     const legRadius = 0.058 + g.bodySize * 0.032;
409:     const positions = [
410:       { x: -bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: 0 },
411:       { x: bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: Math.PI },
412:       { x: -bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: Math.PI },
413:       { x: bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: 0 },
414:     ];
415: 
416:     positions.forEach((entry, i) => {
417:       const root = new THREE.Group();
418:       root.position.set(entry.x, bodyY - bodyH * 0.26, entry.z);
419:       this.model.add(root);
420: 
421:       const shoulder = new THREE.Mesh(this.torsoGeo, this.limbMat);
422:       shoulder.scale.set(legRadius * 1.22, legRadius * 1.25, legRadius * 1.3);
423:       root.add(shoulder);
424: 
425:       const thigh = new THREE.Mesh(this.torsoGeo, this.limbMat);
426:       thigh.scale.set(legRadius * 1.35, upperLen * 0.32, legRadius * 1.35);
427:       thigh.position.y = -upperLen * 0.36;
428:       thigh.castShadow = true;
429:       root.add(thigh);
430: 
431:       const upper = new THREE.Mesh(
432:         new THREE.CylinderGeometry(legRadius * 0.82, legRadius * 0.68, upperLen, 8),
433:         this.limbMat,
434:       );
435:       upper.position.y = -upperLen / 2;
436:       upper.castShadow = true;
437:       root.add(upper);
438: 
439:       const knee = new THREE.Group();
440:       knee.position.y = -upperLen;
441:       root.add(knee);
442: 
443:       const kneeJoint = new THREE.Mesh(this.torsoGeo, this.limbMat);
444:       kneeJoint.scale.setScalar(legRadius * 0.8);
445:       knee.add(kneeJoint);
446: 
447:       const lower = new THREE.Mesh(
448:         new THREE.CylinderGeometry(legRadius * 0.68, legRadius * 0.5, lowerLen, 7),
449:         this.limbMat,
450:       );
451:       lower.position.y = -lowerLen / 2;
452:       lower.castShadow = true;
453:       knee.add(lower);
454: 
455:       const foot = new THREE.Mesh(this.torsoGeo, this.limbMat);
456:       foot.scale.set(legRadius * 1.65, legRadius * 0.58, legRadius * 2.25);
457:       foot.position.set(0, -lowerLen - legRadius * 0.17, legRadius * 0.7);
458:       foot.castShadow = true;
459:       knee.add(foot);
460: 
461:       for (let toe = -1; toe <= 1; toe += 1) {
462:         const claw = new THREE.Mesh(new THREE.ConeGeometry(legRadius * 0.17, legRadius * 0.75, 4), this.darkBoneMat);
463:         claw.position.set(toe * legRadius * 0.62, -lowerLen + legRadius * 0.02, legRadius * 1.9);
464:         claw.rotation.x = Math.PI / 2.4;
465:         knee.add(claw);
466:       }
467: 
468:       this.legs.push({
469:         root,
470:         knee,
471:         phase: entry.phase,
472:         front: entry.front,
473:         upperLen,
474:         lowerLen,
475:         baseRot: entry.front ? 0.05 : -0.04,
476:       });
477:     });
478:   }
479: 
480:   buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
481:     const g = this.genome;
482:     if (g.armor < 0.22) return;
483:     const count = 3 + Math.round(g.armor * 5);
484:     for (let i = 0; i < count; i += 1) {
485:       const t = (i / (count - 1 || 1)) * 1.5 - 0.75;
486:       const z = t * bodyLen * 0.76;
487:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
488:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
489:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
490:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
491:       spike.rotation.x = -0.34 - g.armor * 0.18;
492:       spike.rotation.y = Math.PI / 4;
493:       spike.castShadow = true;
494:       this.model.add(spike);
495:     }
496: 
497:     if (g.armor > 0.62) {
498:       for (const side of [-1, 1]) {
499:         const plate = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.18, 4), this.boneMat);
500:         plate.position.set(side * bodyW * 0.55, bodyY + bodyH * 0.5, bodyLen * 0.55);
501:         plate.rotation.z = side * 0.6;
502:         plate.rotation.x = -0.3;
503:         plate.castShadow = true;
504:         this.model.add(plate);
505:       }
506:     }
507:   }
508: 
509:   buildAccents({ bodyLen, bodyW, bodyH, bodyY }) {
510:     const g = this.genome;
511:     const spotCount = Math.round(1 + g.pattern * 5);
512:     for (let i = 0; i < spotCount; i += 1) {
513:       const side = i % 2 === 0 ? -1 : 1;
514:       const t = (i / Math.max(1, spotCount - 1)) * 1.4 - 0.7;
515:       const spot = new THREE.Mesh(new THREE.SphereGeometry(0.008 + g.pattern * 0.012, 6, 5), this.spotMat);
516:       spot.position.set(side * bodyW * 0.98, bodyY - bodyH * 0.05 + Math.sin(t * 3) * 0.03, t * bodyLen * 0.68);
517:       this.model.add(spot);
518:     }
519:   }
520: 
521:   chooseTarget(initial = false) {
522:     const angle = this.rng() * TAU;
523:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
524:     let x = this.home.x + Math.cos(angle) * dist;
525:     let z = this.home.z + Math.sin(angle) * dist;
526: 
