480:   buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
481:     const g = this.genome;
482:     if (g.armor < 0.22) return;
483:     const count = 3 + Math.round(g.armor * 5);
484:     for (let i = 0; i < count; i += 1) {
485:       const t = (i / (count - 1 || 1)) * 1.5 - 0.75;
486:       const z = t * bodyLen * 0.76;
487:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
488:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
489:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
490:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
491:       spike.rotation.x = -0.34 - g.armor * 0.18;
492:       spike.rotation.y = Math.PI / 4;
493:       spike.castShadow = true;
494:       this.model.add(spike);
495:     }
496: 
497:     if (g.armor > 0.62) {
498:       for (const side of [-1, 1]) {
499:         const plate = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.18, 4), this.boneMat);
500:         plate.position.set(side * bodyW * 0.55, bodyY + bodyH * 0.5, bodyLen * 0.55);
501:         plate.rotation.z = side * 0.6;
502:         plate.rotation.x = -0.3;
503:         plate.castShadow = true;
504:         this.model.add(plate);
505:       }
506:     }
507:   }
