471: function advanceGeneration({ automatic = false } = {}) {
472:   if (state.transitioning) return;
473:   hideHint();
474:   state.transitioning = true;
475:   const before = meanFitness();
476:   const parents = rankPopulation(state.population);
477:   const seeded = breedPopulation(state.population, state.env, random);
478:   const nextOrganisms = seeded.map((item) => makeOrganism(item.genome, {
479:     origin: item.origin,
480:     changes: item.changes,
481:     parents: item.parents,
482:   }));
483: 
484:   state.population = nextOrganisms;
485:   state.generation += 1;
486:   state.mutagen = Math.min(5, state.mutagen + 2);
487:   state.autoTimer = 0;
488:   creatures.selectedIndex = 0;
489:   creatures.spawnPopulation(state.population, SPAWN_POSITIONS);
490:   creatures.select(0, true);
491: 
492:   recordHistory();
493:   const mean = meanFitness();
494:   const top = rankPopulation(state.population)[0];
495:   const pressure = pickDominantPressure(top);
496:   const changes = nextOrganisms.flatMap((org) => org.changes || []);
497:   const strongest = changes.sort((a, b) => Math.abs(b.delta) - Math.abs(a.delta))[0];
498: 
499:   els.btnAuto.classList.toggle("paused", !state.auto);
500: 
501:   addLog(
502:     `Generation ${pad(state.generation)} hatched. Mean fitness <b>${mean.toFixed(1)}</b>; ${pressure} led selection.`,
503:     true,
504:   );
505:   if (strongest) {
506:     const desc = describeChange(strongest);
507:     addLog(`Dominant mutation: ${desc.detail.toLowerCase()} — ${desc.title}.`);
508:   } else {
509:     addLog(`The leading genome was preserved intact. ${parents.length ? "Stability can be a strategy." : ""}`);
510:   }
511: 
512:   const selectedCreature = creatures.selected;
513:   if (selectedCreature) {
514:     world.burst(selectedCreature.position, selectedCreature.accentColor ?? 0xcaff72, 1.15);
515:   }
516: 
517:   const gain = mean - before;
518:   showToast(
519:     `Generation ${pad(state.generation)} hatched`,
520:     `${gain >= 0 ? "+" : "−"}${Math.abs(gain).toFixed(1)} fitness · ${state.population.filter((o) => o.changes.length).length} new alleles`,
521:     strongest ? "◈" : "✦",
522:     3000,
523:   );
524:   if (automatic) addLog("Automatic selection advanced the lineage.");
525:   updateAll();
526:   audio.evolve();
527: 
528:   if (!state.milestoneShown && state.generation >= 5 && mean >= 72) {
529:     state.milestoneShown = true;
530:     setTimeout(() => {
531:       showToast("Stable lineage established", `${mean.toFixed(1)} mean fitness · the basin is adapting around your creatures`, "❖", 5200);
532:       addLog("Milestone: a stable lineage now occupies the basin.", true);
533:     }, 900);
534:   }
535: 
536:   setTimeout(() => {
537:     state.transitioning = false;
538:   }, 360);
539: }
