57:     if (key === "hue") {
58:       lo = 0.28;
59:       hi = 0.74;
60:     }
61:     if (key === "pattern") {
62:       lo = 0.25;
63:       hi = 0.8;
64:     }
65:     genome[key] = Math.min(1, Math.max(0, lo + rng() * (hi - lo)));
66:   }
67:   return genome;
