70: export function crossover(a, b, rng = Math.random) {
71:   const child = {};
72:   for (const key of GENE_KEYS) {
73:     const t = rng();
74:     const value = t < 0.44 ? a[key] : t < 0.88 ? b[key] : (a[key] + b[key]) / 2;
75:     child[key] = clamp01(value + gaussian(rng) * 0.018);
76:   }
77:   return child;
78: }
