80: export function mutate(genome, rng = Math.random, rate = 0.2, power = 0.115) {
81:   const result = { ...genome };
82:   const changes = [];
83:   for (const key of GENE_KEYS) {
84:     if (rng() < rate) {
85:       const before = result[key];
86:       const step = gaussian(rng) * power;
87:       result[key] = clamp01(before + step);
88:       if (Math.abs(result[key] - before) > 0.004) {
89:         changes.push({
90:           gene: key,
91:           code: GENE_META[key].code,
92:           before,
93:           after: result[key],
94:           delta: result[key] - before,
95:         });
96:       }
97:     }
98:   }
99:   return { genome: result, changes };
100: }
