102: export function mutateGene(genome, key, rng = Math.random, power = 0.16) {
103:   const next = { ...genome };
104:   const before = next[key];
105:   next[key] = clamp01(before + gaussian(rng) * power);
106:   return {
107:     genome: next,
108:     changes: [{ gene: key, code: GENE_META[key].code, before, after: next[key], delta: next[key] - before }],
109:   };
