220:   buildIsland() {
221:     const group = new THREE.Group();
222:     this.root.add(group);
223:     this.island = group;
224: 
225:     // Top soil mesh, built as a radial grid so the rim can ripple organically.
226:     const rings = 30;
227:     const segments = 128;
228:     const radius = 10.45;
229:     const positions = [];
230:     const colors = [];
231:     const uvs = [];
232:     const indices = [];
233:     const color = new THREE.Color();
234:     const rng = mulberry32(9);
235: 
236:     // center
237:     positions.push(0, terrainHeight(0, 0), 0);
238:     color.setHSL(0.23 + rng() * 0.018, 0.28, 0.31);
239:     colors.push(color.r, color.g, color.b);
240:     uvs.push(0.5, 0.5);
241: 
242:     for (let ring = 1; ring <= rings; ring += 1) {
243:       const rr = (ring / rings) * radius;
244:       for (let s = 0; s < segments; s += 1) {
245:         const a = (s / segments) * Math.PI * 2;
246:         const wobble = 1 + Math.sin(a * 5 + 1.2) * 0.012 + Math.sin(a * 9 - 2) * 0.006;
247:         const x = Math.cos(a) * rr * wobble;
248:         const z = Math.sin(a) * rr * wobble;
249:         const y = terrainHeight(x, z);
250:         positions.push(x, y, z);
251:         const clearing = 1 - smooth(1.8, 4.2, Math.hypot(x, z));
252:         const moisture = 1 - smooth(2.0, 4.4, Math.hypot(x - POND.x, z - POND.z));
253:         const rim = smooth(8.8, 10.4, rr);
254:         color.setHSL(
255:           0.205 + Math.sin(x * 0.82 + z * 0.4) * 0.018 + clearing * 0.018,
256:           0.24 + moisture * 0.13 - rim * 0.09,
257:           0.265 + Math.sin(z * 0.7) * 0.02 + clearing * 0.055 + rim * 0.012,
258:         );
259:         colors.push(color.r, color.g, color.b);
260:         uvs.push(x / (radius * 2) + 0.5, z / (radius * 2) + 0.5);
261:       }
262:     }
263: 
264:     for (let s = 0; s < segments; s += 1) {
265:       indices.push(0, 1 + ((s + 1) % segments), 1 + s);
266:     }
267:     for (let ring = 1; ring < rings; ring += 1) {
268:       const rowA = 1 + (ring - 1) * segments;
269:       const rowB = 1 + ring * segments;
270:       for (let s = 0; s < segments; s += 1) {
271:         const next = (s + 1) % segments;
272:         const a = rowA + s;
273:         const b = rowA + next;
274:         const c = rowB + s;
275:         const d = rowB + next;
276:         indices.push(a, b, c, b, d, c);
277:       }
278:     }
279: 
280:     const geometry = new THREE.BufferGeometry();
281:     geometry.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
282:     geometry.setAttribute("color", new THREE.Float32BufferAttribute(colors, 3));
283:     geometry.setAttribute("uv", new THREE.Float32BufferAttribute(uvs, 2));
284:     geometry.setIndex(indices);
285:     geometry.computeVertexNormals();
286: 
287:     const terrainMap = makeNoiseTexture(512, "#c7c8b8", 12);
288:     terrainMap.repeat.set(3.2, 3.2);
289:     const terrainMaterial = new THREE.MeshStandardMaterial({
290:       map: terrainMap,
291:       vertexColors: true,
292:       roughness: 0.96,
293:       metalness: 0,
294:     });
295:     const terrain = new THREE.Mesh(geometry, terrainMaterial);
296:     terrain.receiveShadow = true;
297:     group.add(terrain);
298:     this.terrain = terrain;
299: 
300:     // Soft worn clearing beneath the population.
301:     const clearingTexture = makeGroundClearingTexture();
302:     const clearing = new THREE.Mesh(
303:       new THREE.CircleGeometry(3.7, 64),
304:       new THREE.MeshStandardMaterial({
305:         map: clearingTexture,
306:         transparent: true,
307:         roughness: 1,
308:         depthWrite: false,
309:         opacity: 0.85,
310:       }),
311:     );
312:     clearing.rotation.x = -Math.PI / 2;
313:     clearing.position.y = 0.023;
314:     clearing.receiveShadow = true;
315:     group.add(clearing);
316: 
317:     // Thick rocky underside.
318:     const rimGeo = new THREE.CylinderGeometry(radius, 9.82, 1.35, 96, 2, false);
319:     const rimMat = new THREE.MeshStandardMaterial({ color: 0x26322d, roughness: 0.92, metalness: 0.04 });
320:     const rim = new THREE.Mesh(rimGeo, rimMat);
321:     rim.position.y = -0.675;
322:     rim.receiveShadow = true;
323:     rim.castShadow = true;
324:     group.add(rim);
325: 
326:     const strata = [
327:       { r: 9.8, y: -1.04, h: 0.28, color: 0x1b2722, rot: 0.16 },
328:       { r: 9.4, y: -1.45, h: 0.28, color: 0x374038, rot: -0.2 },
329:       { r: 9.05, y: -1.84, h: 0.3, color: 0x1d2925, rot: 0.3 },
330:     ];
331:     for (const layer of strata) {
332:       const mesh = new THREE.Mesh(
333:         new THREE.CylinderGeometry(layer.r, layer.r - 0.22, layer.h, 96, 1),
334:         new THREE.MeshStandardMaterial({ color: layer.color, roughness: 0.96, metalness: 0.02 }),
335:       );
336:       mesh.position.y = layer.y;
337:       mesh.rotation.y = layer.rot;
338:       group.add(mesh);
339:     }
340: 
341:     const keelGeo = new THREE.ConeGeometry(8.7, 4.8, 24, 4);
342:     const keel = new THREE.Mesh(
343:       keelGeo,
344:       new THREE.MeshStandardMaterial({ color: 0x131c19, roughness: 0.98, flatShading: true }),
345:     );
346:     keel.rotation.x = Math.PI;
347:     keel.rotation.y = 0.1;
348:     keel.position.y = -4.92;
349:     group.add(keel);
350: 
351:     // Holographic edge rings give the diorama a laboratory frame.
352:     const edgeRing = new THREE.Mesh(
353:       new THREE.TorusGeometry(radius + 0.03, 0.012, 6, 160),
354:       new THREE.MeshBasicMaterial({ color: 0x7affe0, transparent: true, opacity: 0.42 }),
355:     );
356:     edgeRing.rotation.x = Math.PI / 2;
357:     edgeRing.position.y = 0.026;
358:     group.add(edgeRing);
359: 
360:     const lowerRing = new THREE.Mesh(
361:       new THREE.TorusGeometry(9.22, 0.018, 6, 160),
362:       new THREE.MeshBasicMaterial({ color: 0x4feac5, transparent: true, opacity: 0.38 }),
363:     );
364:     lowerRing.rotation.x = Math.PI / 2;
365:     lowerRing.position.y = -1.62;
366:     group.add(lowerRing);
367:     this.edgeRings = [edgeRing, lowerRing];
368: 
369:     const tickMaterial = new THREE.MeshBasicMaterial({ color: 0xa9ffe1, transparent: true, opacity: 0.36 });
370:     for (let i = 0; i < 32; i += 1) {
371:       const a = (i / 32) * Math.PI * 2;
372:       const tick = new THREE.Mesh(new THREE.BoxGeometry(0.012, 0.012, i % 4 === 0 ? 0.34 : 0.16), tickMaterial);
373:       tick.position.set(Math.cos(a) * (radius + 0.35), 0.01, Math.sin(a) * (radius + 0.35));
374:       tick.rotation.y = -a + Math.PI / 2;
375:       group.add(tick);
376:     }
377: 
378:     this.addRocks(group);
379:   }
