325: export function describeChange(change) {
326:   const meta = GENE_META[change.gene];
327:   const direction = change.delta > 0 ? "+" : "−";
328:   const value = Math.abs(change.delta);
329:   let phrase = `${meta.code} shift`;
330:   if (value > 0.16) phrase = `${meta.code} regulatory leap`;
331:   else if (value < 0.05) phrase = `${meta.code} micro-variant`;
332:   return {
333:     title: `${meta.label} ${direction}${Math.round(value * 100)}%`,
334:     detail: phrase,
335:     direction: change.delta > 0 ? "up" : "down",
336:   };
337: }
