260: export function diversity(population) {
261:   if (population.length < 2) return 0;
262:   let sum = 0;
263:   let count = 0;
264:   for (let i = 0; i < population.length; i += 1) {
265:     for (let j = i + 1; j < population.length; j += 1) {
266:       let d = 0;
267:       for (const key of GENE_KEYS) {
268:         d += Math.abs(population[i].genome[key] - population[j].genome[key]);
269:       }
270:       sum += d / GENE_KEYS.length;
271:       count += 1;
272:     }
273:   }
274:   return sum / count;
275: }
276: 
277: export function rankPopulation(population) {
278:   return [...population].sort((a, b) => b.evaluation.fitness - a.evaluation.fitness);
279: }
280: 
281: export function breedPopulation(population, env, rng = Math.random) {
282:   const ranked = rankPopulation(population);
283:   const eliteCount = Math.max(2, Math.round(population.length * 0.34));
284:   const parents = ranked.slice(0, Math.max(3, eliteCount));
285:   const next = [];
286: 
287:   // A true survivor keeps its exact alleles and becomes the first hatchling.
288:   next.push({ genome: { ...parents[0].genome }, origin: "elite", changes: [] });
289: 
290:   while (next.length < population.length) {
291:     const a = weightedParent(parents, rng);
292:     let b = weightedParent(parents, rng);
293:     if (parents.length > 1) {
294:       let guard = 0;
295:       while (b === a && guard < 8) {
296:         b = weightedParent(parents, rng);
297:         guard += 1;
298:       }
299:     }
300:     let genome = a === b ? { ...a.genome } : crossover(a.genome, b.genome, rng);
301:     const mutation = mutate(genome, rng, next.length === 1 ? 0.08 : 0.18, 0.1);
302:     genome = mutation.genome;
303:     next.push({
304:       genome,
305:       origin: next.length === 1 ? "elite-mutant" : "offspring",
306:       changes: mutation.changes,
307:       parents: [a.id, b.id],
308:     });
309:   }
310: 
311:   return next;
312: }
313: 
314: function weightedParent(parents, rng) {
315:   const weights = parents.map((p) => Math.pow(Math.max(1, p.evaluation.fitness), 2.4));
316:   const total = weights.reduce((a, b) => a + b, 0);
317:   let roll = rng() * total;
318:   for (let i = 0; i < parents.length; i += 1) {
319:     roll -= weights[i];
320:     if (roll <= 0) return parents[i];
321:   }
322:   return parents[parents.length - 1];
323: }
