15:   return `hsl(${h}, ${s}%, ${l}%)`;
16: }
17: 
18: function makeSkinTexture(genome, seed) {
19:   const size = 384;
20:   const canvas = document.createElement("canvas");
21:   canvas.width = size;
22:   canvas.height = size;
23:   const ctx = canvas.getContext("2d");
24:   const rng = mulberry32(seed * 997 + 17);
25:   const hue = 48 + genome.hue * 102;
26:   const saturation = 25 + genome.pattern * 20;
27:   const lightness = 31 + genome.hue * 9;
28:   ctx.fillStyle = hsl(hue, saturation, lightness);
29:   ctx.fillRect(0, 0, size, size);
30: 
31:   // Soft dorsal gradient.
32:   const grad = ctx.createLinearGradient(0, 0, 0, size);
33:   grad.addColorStop(0, hsl(hue - 5, saturation + 7, lightness - 10));
34:   grad.addColorStop(0.55, hsl(hue, saturation, lightness + 1));
35:   grad.addColorStop(1, hsl(hue + 8, saturation - 8, lightness + 16));
36:   ctx.globalAlpha = 0.55;
37:   ctx.fillStyle = grad;
38:   ctx.fillRect(0, 0, size, size);
39:   ctx.globalAlpha = 1;
40: 
41:   const spots = Math.floor(28 + genome.pattern * 115);
42:   for (let i = 0; i < spots; i += 1) {
43:     const x = rng() * size;
44:     const y = rng() * size;
45:     const rx = 2 + rng() * (5 + genome.pattern * 12);
46:     const ry = rx * (0.45 + rng() * 0.7);
47:     ctx.fillStyle = rng() > 0.42
48:       ? `hsla(${hue - 8 - rng() * 18}, ${saturation + 10}%, ${lightness - 13 - rng() * 12}%, ${0.25 + rng() * 0.38})`
49:       : `hsla(${hue + 9}, ${saturation + 2}%, ${lightness + 12}%, ${0.14 + rng() * 0.22})`;
50:     ctx.beginPath();
51:     ctx.ellipse(x, y, rx, ry, rng() * Math.PI, 0, Math.PI * 2);
52:     ctx.fill();
53:   }
54: 
55:   if (genome.pattern > 0.34) {
56:     const stripes = 4 + Math.floor(genome.pattern * 7);
57:     ctx.globalAlpha = 0.13 + genome.pattern * 0.2;
58:     ctx.strokeStyle = hsl(hue - 12, saturation + 14, lightness - 20);
59:     ctx.lineWidth = 3 + genome.pattern * 7;
60:     for (let i = 0; i < stripes; i += 1) {
61:       const x = (i / stripes) * size + rng() * 10;
62:       ctx.beginPath();
63:       ctx.moveTo(x, -10);
64:       ctx.bezierCurveTo(x + 15, size * 0.3, x - 18, size * 0.7, x + 8, size + 10);
65:       ctx.stroke();
66:     }
67:     ctx.globalAlpha = 1;
68:   }
69: 
70:   // Fine dermal speckle.
71:   for (let i = 0; i < 1200; i += 1) {
72:     const x = rng() * size;
73:     const y = rng() * size;
74:     ctx.fillStyle = `rgba(20, 34, 26, ${0.025 + rng() * 0.09})`;
75:     ctx.fillRect(x, y, 0.8 + rng() * 1.6, 0.8 + rng() * 1.6);
76:   }
77: 
78:   const texture = new THREE.CanvasTexture(canvas);
79:   texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
80:   texture.colorSpace = THREE.SRGBColorSpace;
81:   texture.anisotropy = 4;
82:   return { texture, hue, saturation, lightness };
83: }
