239:     { score: genome.crest, name: "Crest" },
240:     { score: genome.fat, name: "Drifter" },
241:   ].sort((a, b) => b.score - a.score);
242:   const suffix = candidates[0].score > 0.58 ? candidates[0].name : "Walker";
243: 
244:   let genus = "Aurelia";
