299:   els.fitEnergy.textContent = Math.round(org.evaluation.components.efficiency);
300: 
301:   const status = fitness >= 72 ? "Thriving" : fitness >= 56 ? "Stable" : "Stressed";
302:   els.status.textContent = status;
303:   els.status.style.color = fitness >= 56 ? "var(--mint)" : "var(--coral)";
304:   els.diet.textContent = org.genome.armor > 0.66 ? "Omnivore" : org.genome.neck > 0.62 ? "Browser" : "Grazer";
305:   els.plan.textContent = org.genome.legs > 0.66 ? "Cursorial" : "Quadruped";
306: 
307:   const weightValues = org.evaluation.weights;
308:   const weightTotal = Object.values(weightValues).reduce((sum, value) => sum + value, 0);
309:   for (const key of ["thermal", "foraging", "defense", "efficiency"]) {
310:     const percentage = (weightValues[key] / weightTotal) * 100;
311:     els.weights[key][0].style.width = `${percentage}%`;
312:     els.weights[key][1].textContent = `${Math.round(percentage)}%`;
313:   }
314: 
315:   const targets = traitTargets(state.env);
316:   const rows = [...els.traitList.querySelectorAll(".trait")];
317:   for (const row of rows) {
318:     const key = row.dataset.gene;
319:     const raw = org.genome[key];
320:     row.querySelector("[data-value]").textContent = traitDisplay(key, raw);
321:     row.querySelector("[data-fill]").style.width = `${clamp(raw, 0, 1) * 100}%`;
322:     const optimum = row.querySelector("[data-optimum]");
323:     optimum.style.left = `${clamp(targets[key] ?? 0.5, 0.02, 0.98) * 100}%`;
324:   }
325: 
326:   els.mutagenPips.innerHTML = Array.from({ length: 5 }, (_, i) => `<i class="${i < state.mutagen ? "full" : ""}"></i>`).join("");
327:   els.btnMutate.disabled = state.mutagen <= 0;
