834: function gameLoop(now) {
835:   const rawDt = Math.min(1, (now - (gameLoop.last || now)) / 1000);
836:   const dt = Math.min(0.05, rawDt);
837:   gameLoop.last = now;
838:   creatures.update(dt);
839:   updateCreatureTag();
840: 
841:   if (state.auto) {
842:     // Auto-evolution runs on wall-clock time so software rendering or a
843:     // slow frame never stretches "one generation every N seconds".
844:     state.autoTimer += rawDt * state.speed;
845:     if (state.autoTimer >= 6 && !state.transitioning) {
846:       state.autoTimer = 0;
847:       advanceGeneration({ automatic: true });
848:     }
849:   }
