1052:   tick() {
1053:     const dt = Math.min(this.clock.getDelta(), 0.05);
1054:     this.time += dt;
1055: 
1056:     this.updateEnvironmentLerp(dt);
1057:     this.updateBursts(dt);
1058:     this.controls.update();
1059: 
1060:     // Camera target eases toward the selected creature without breaking orbit.
1061:     const focusK = 1 - Math.exp(-dt * 1.8);
1062:     this.controls.target.x += (this.selectionFocus.x - this.controls.target.x) * focusK;
1063:     this.controls.target.y += (this.selectionFocus.y - this.controls.target.y) * focusK;
1064:     this.controls.target.z += (this.selectionFocus.z - this.controls.target.z) * focusK;
1065: 
1066:     if (this.selectionRing?.visible) {
1067:       this.selectionRing.rotation.y += dt * 0.32;
1068:       const pulse = 1 + Math.sin(this.time * 2.1) * 0.032;
1069:       this.selectionRing.scale.setScalar((this._selectionBaseScale || 1.5) * pulse);
1070:       this.selectionRingMat.opacity = 0.62 + Math.sin(this.time * 2.1) * 0.14;
1071:     }
1072: 
1073:     for (let i = 0; i < this.ripples.length; i += 1) {
1074:       const ripple = this.ripples[i];
1075:       const t = (this.time * 0.14 + ripple.offset) % 2.6;
1076:       const scale = 0.45 + t * 1.25;
1077:       ripple.mesh.scale.set(1.2 * scale, 0.82 * scale, 1);
1078:       ripple.mesh.material.opacity = Math.max(0, 0.24 * (1 - t / 2.6));
1079:     }
1080:     if (this.water) {
1081:       this.water.position.y = 0.075 + Math.sin(this.time * 0.8) * 0.003;
1082:     }
1083: 
1084:     if (this.sporeCloud) {
1085:       this.sporeCloud.rotation.y = this.time * 0.004;
1086:       this.sporeCloud.position.y = Math.sin(this.time * 0.12) * 0.08;
1087:     }
1088: 
1089:     for (const sprite of this.fireflies) {
1090:       const data = sprite.userData;
1091:       const a = data.angle + this.time * data.speed;
1092:       sprite.position.set(
1093:         Math.cos(a) * data.radius + Math.sin(this.time * 0.7 + data.phase) * data.wobble,
1094:         data.baseY + Math.sin(this.time * 0.55 + data.phase) * 0.22,
1095:         Math.sin(a) * data.radius + Math.cos(this.time * 0.61 + data.phase) * data.wobble,
1096:       );
1097:       sprite.material.opacity = 0.35 + (Math.sin(this.time * 2.2 + data.phase) + 1) * 0.18;
1098:     }
1099: 
1100:     for (const pair of this.predatorEyes) {
1101:       if (!pair.visible) continue;
1102:       const target = pair.userData.targetScale || 0;
