622:     const positions = [
623:       [-7.6, -6.6, 3.5],
624:       [-2.6, -8.6, 2.8],
625:       [5.6, -7.7, 3.9],
626:       [8.1, -3.2, 2.7],
627:       [-8.9, 1.2, 2.5],
