94: export class Creature {
95:   constructor({ genome, evaluation, world, rng, index, position }) {
96:     this.genome = genome;
97:     this.evaluation = evaluation;
98:     this.world = world;
99:     this.rng = rng;
100:     this.index = index;
101:     this.nameData = nameCreature(genome);
102:     this.spawnTime = world.time;
103:     this.group = new THREE.Group();
104:     this.group.userData.creature = this;
105:     this.group.userData.creatureId = index;
106:     this.model = new THREE.Group();
107:     this.group.add(this.model);
108:     this.world.addLifeObject(this.group);
109: 
110:     this.position = new THREE.Vector3(position.x, terrainHeight(position.x, position.z), position.z);
111:     this.home = this.position.clone();
112:     this.group.position.copy(this.position);
113:     this.heading = rng() * TAU;
114:     this.group.rotation.y = this.heading;
115:     this.target = this.position.clone();
116:     this.walkPhase = rng() * TAU;
117:     this.blinkPhase = rng() * 8;
118:     this.moving = false;
119:     this.selected = false;
120:     this.dimensions = {};
121:     this.movementSpeed = 0.8;
122:     this.legs = [];
123:     this.tailJoints = [];
124:     this.eyes = [];
125:     this.crestMeshes = [];
126:     this.tempTarget = new THREE.Vector3();
127: 
128:     this.build();
129:     this.chooseTarget(true);
130:     if (index === 0) {
131:       this.heading = Math.atan2(
132:         world.camera.position.x - this.position.x,
133:         world.camera.position.z - this.position.z,
134:       );
135:       this.group.rotation.y = this.heading;
136:       this.target.set(
137:         this.position.x + Math.sin(this.heading) * 1.2,
138:         this.position.y,
139:         this.position.z + Math.cos(this.heading) * 1.2,
140:       );
141:     }
142:   }
143: 
144:   get radius() {
145:     return (0.58 + this.genome.bodySize * 0.42) * (0.82 + this.genome.bodySize * 0.5);
146:   }
147: 
148:   build() {
149:     const g = this.genome;
150:     const rng = this.rng;
151:     const sizeScale = 0.82 + g.bodySize * 0.55;
152:     this.sizeScale = sizeScale;
153:     this.model.scale.setScalar(0.01);
154:     this.spawnTime = this.world.time;
155: 
156:     const skin = makeSkinTexture(g, this.index + 3);
157:     this.skinTexture = skin.texture;
158:     const hue = skin.hue;
159:     const baseColor = new THREE.Color().setHSL(hue / 360, skin.saturation / 100, skin.lightness / 100, THREE.SRGBColorSpace);
160:     const accentColor = new THREE.Color().setHSL(((hue + 48) % 360) / 360, 0.46, 0.36, THREE.SRGBColorSpace);
161:     const bellyColor = new THREE.Color().setHSL(((hue + 14) % 360) / 360, 0.22, 0.57, THREE.SRGBColorSpace);
162:     const limbColor = new THREE.Color().setHSL(((hue - 2) % 360) / 360, 0.3, 0.28, THREE.SRGBColorSpace);
