336:     const nostrilGeo = new THREE.SphereGeometry(headR * 0.05, 6, 4);
337:     for (const side of [-1, 1]) {
338:       const nostril = new THREE.Mesh(nostrilGeo, this.eyeMat);
339:       nostril.position.set(side * headR * 0.18, -headR * 0.02, headR * 1.86);
