11: const clamp = (v, min, max) => Math.max(min, Math.min(max, v));
12: const smooth = (edge0, edge1, x) => {
13:   const t = clamp((x - edge0) / (edge1 - edge0), 0, 1);
14:   return t * t * (3 - 2 * t);
15: };
