27: function makeNoiseTexture(size = 512, base = "#b5b8a6", seed = 7) {
28:   const rng = mulberry32(seed);
29:   const canvas = document.createElement("canvas");
30:   canvas.width = size;
31:   canvas.height = size;
32:   const ctx = canvas.getContext("2d");
33:   ctx.fillStyle = base;
34:   ctx.fillRect(0, 0, size, size);
35:   for (let i = 0; i < 9000; i += 1) {
36:     const x = rng() * size;
37:     const y = rng() * size;
38:     const radius = 0.4 + rng() * 4.4;
39:     const shade = Math.floor(70 + rng() * 90);
40:     ctx.fillStyle = `rgba(${shade}, ${shade}, ${shade - 8}, ${0.04 + rng() * 0.14})`;
41:     ctx.beginPath();
42:     ctx.arc(x, y, radius, 0, Math.PI * 2);
43:     ctx.fill();
44:   }
45:   for (let i = 0; i < 170; i += 1) {
46:     const x = rng() * size;
47:     const y = rng() * size;
48:     ctx.strokeStyle = `rgba(55, 55, 48, ${0.03 + rng() * 0.09})`;
49:     ctx.lineWidth = 0.5 + rng() * 1.6;
50:     ctx.beginPath();
51:     ctx.moveTo(x, y);
52:     ctx.quadraticCurveTo(x + rng() * 25 - 12, y + rng() * 25 - 12, x + rng() * 48 - 24, y + rng() * 48 - 24);
53:     ctx.stroke();
54:   }
55:   const texture = new THREE.CanvasTexture(canvas);
56:   texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
57:   texture.colorSpace = THREE.SRGBColorSpace;
58:   texture.anisotropy = 4;
59:   return texture;
60: }
