652:         const spread = 0.65 + rng() * 0.55;
653:         canopy.scale.set(spread * (0.8 + rng() * 0.5), spread * 0.4, spread * (0.7 + rng() * 0.5));
654:         canopy.position.set(
655:           (rng() - 0.5) * 1.65,
656:           trunkHeight + (rng() - 0.15) * 0.85,
657:           (rng() - 0.5) * 1.4,
658:         );
659:         canopy.rotation.set(rng() * 0.5, rng() * 6, rng() * 0.4);
660:         canopy.castShadow = true;
661:         canopy.receiveShadow = true;
662:         tree.add(canopy);
663:       }
664:       group.add(tree);
665:     });
