684:   select(index, updateFocus = true) {
685:     this.selectedIndex = Math.max(0, Math.min(this.creatures.length - 1, index));
686:     const creature = this.creatures[this.selectedIndex];
687:     if (!creature) return null;
688:     if (updateFocus) {
689:       this.world.setSelection(creature.position, creature.radius);
