694:   replace(index, organism) {
695:     const old = this.creatures[index];
696:     if (!old) return null;
697:     const position = old.position.clone();
698:     const wasSelected = this.selectedIndex === index;
699:     old.dispose();
700:     const creature = new Creature({
701:       genome: organism.genome,
702:       evaluation: organism.evaluation,
703:       world: this.world,
704:       rng: mulberry32(7103 + index * 193 + organism.id * 7),
705:       index,
706:       position,
707:     });
708:     organism.creature = creature;
709:     this.creatures[index] = creature;
710:     if (wasSelected) this.select(index);
711:     return creature;
