394:     if (g.armor > 0.58) {
395:       const club = new THREE.Mesh(new THREE.IcosahedronGeometry(0.12 + g.armor * 0.1, 0), this.boneMat);
396:       club.position.z = -segLen * 0.92;
397:       club.scale.set(1.2, 0.85, 1.35);
398:       club.rotation.set(0.2, 0.4, 0.1);
399:       club.castShadow = true;
400:       parent.add(club);
