509:   buildAccents({ bodyLen, bodyW, bodyH, bodyY }) {
510:     const g = this.genome;
511:     const spotCount = Math.round(1 + g.pattern * 5);
512:     for (let i = 0; i < spotCount; i += 1) {
513:       const side = i % 2 === 0 ? -1 : 1;
514:       const t = (i / Math.max(1, spotCount - 1)) * 1.4 - 0.7;
515:       const spot = new THREE.Mesh(new THREE.SphereGeometry(0.008 + g.pattern * 0.012, 6, 5), this.spotMat);
516:       spot.position.set(side * bodyW * 0.98, bodyY - bodyH * 0.05 + Math.sin(t * 3) * 0.03, t * bodyLen * 0.68);
517:       this.model.add(spot);
518:     }
519:   }
