521:   chooseTarget(initial = false) {
522:     const angle = this.rng() * TAU;
523:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
524:     let x = this.home.x + Math.cos(angle) * dist;
525:     let z = this.home.z + Math.sin(angle) * dist;
526: 
527:     if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.8) {
528:       x = this.home.x - Math.cos(angle) * dist;
529:       z = this.home.z - Math.sin(angle) * dist;
530:     }
531:     const r = Math.hypot(x, z);
532:     if (r > 7.1) {
533:       x *= 7.1 / r;
534:       z *= 7.1 / r;
535:     }
536:     this.target.set(x, 0, z);
537:   }
538: 
539:   update(dt) {
540:     const elapsed = this.world.time - this.spawnTime;
541:     const spawnT = clamp01(elapsed / 0.8);
542:     this.model.scale.setScalar(this.sizeScale * Math.max(0.01, easeOutBack(spawnT)));
543:     this.model.visible = spawnT > 0;
544:     if (spawnT < 1) {
545:       this.model.rotation.z = Math.sin(spawnT * Math.PI) * 0.04;
546:       return;
547:     }
548:     this.model.rotation.z *= 0.9;
549: 
550:     const speedGene = 0.6 + this.genome.speed * 1.45;
551:     this.tempTarget.set(this.target.x - this.position.x, 0, this.target.z - this.position.z);
552:     const distance = this.tempTarget.length();
553:     if (distance < 0.22 || this.rng() < dt * 0.008) {
554:       this.chooseTarget();
555:     }
556: 
557:     const moving = distance > 0.35;
558:     this.moving = moving;
559:     if (moving) {
560:       this.tempTarget.normalize();
561:       const desired = Math.atan2(this.tempTarget.x, this.tempTarget.z);
562:       let diff = desired - this.heading;
563:       while (diff > Math.PI) diff -= TAU;
564:       while (diff < -Math.PI) diff += TAU;
565:       this.heading += diff * Math.min(1, dt * 2.4);
566:       this.group.rotation.y = this.heading;
567: 
568:       const step = Math.min(distance, dt * (0.16 + speedGene * 0.22));
569:       const nx = this.position.x + Math.sin(this.heading) * step;
570:       const nz = this.position.z + Math.cos(this.heading) * step;
571:       if (Math.hypot(nx - POND.x, nz - POND.z) > POND.radius + 0.5 && Math.hypot(nx, nz) < 7.35) {
572:         this.position.x = nx;
573:         this.position.z = nz;
574:       } else {
575:         this.chooseTarget();
576:       }
577:       this.walkPhase += dt * (3.9 + speedGene * 2.8);
578:     } else {
579:       this.walkPhase += dt * 1.1;
580:     }
581: 
582:     this.position.y = terrainHeight(this.position.x, this.position.z);
583:     this.group.position.x = this.position.x;
584:     this.group.position.z = this.position.z;
585:     this.group.position.y = this.position.y;
586: 
587:     const stride = moving ? 1 : 0.25;
588:     for (const leg of this.legs) {
589:       const swing = Math.sin(this.walkPhase + leg.phase) * 0.54 * stride;
590:       const lift = Math.max(0, Math.sin(this.walkPhase + leg.phase + Math.PI / 2)) * 0.28 * stride;
591:       leg.root.rotation.x = leg.baseRot + swing;
592:       leg.knee.rotation.x = -lift + (leg.front ? 0.18 : 0.32);
593:     }
594: 
595:     const bob = moving ? Math.abs(Math.sin(this.walkPhase)) * 0.026 : Math.sin(this.world.time * 1.4) * 0.006;
596:     this.model.position.y = bob;
597:     this.model.rotation.x = moving ? Math.sin(this.walkPhase) * 0.008 : 0;
598: 
599:     if (this.neckGroup) {
600:       this.neckGroup.rotation.z = Math.sin(this.walkPhase * 0.5 + 1.2) * 0.022;
601:       this.neckGroup.rotation.x = (0.62 + this.genome.neck * 0.2) + Math.sin(this.walkPhase * 0.5) * 0.027;
