102:     this.spawnTime = world.time;
103:     this.group = new THREE.Group();
104:     this.group.userData.creature = this;
105:     this.group.userData.creatureId = index;
106:     this.model = new THREE.Group();
107:     this.group.add(this.model);
108:     this.world.addLifeObject(this.group);
109: 
110:     this.position = new THREE.Vector3(position.x, terrainHeight(position.x, position.z), position.z);
111:     this.home = this.position.clone();
112:     this.group.position.copy(this.position);
113:     this.heading = rng() * TAU;
114:     this.group.rotation.y = this.heading;
115:     this.target = this.position.clone();
116:     this.walkPhase = rng() * TAU;
117:     this.blinkPhase = rng() * 8;
118:     this.moving = false;
119:     this.selected = false;
120:     this.dimensions = {};
121:     this.movementSpeed = 0.8;
122:     this.legs = [];
123:     this.tailJoints = [];
124:     this.eyes = [];
125:     this.crestMeshes = [];
126:     this.tempTarget = new THREE.Vector3();
127: 
128:     this.build();
129:     this.chooseTarget(true);
130:     if (index === 0) {
131:       this.heading = Math.atan2(
132:         world.camera.position.x - this.position.x,
133:         world.camera.position.z - this.position.z,
134:       );
135:       this.group.rotation.y = this.heading;
136:       this.target.set(
137:         this.position.x + Math.sin(this.heading) * 1.2,
138:         this.position.y,
139:         this.position.z + Math.cos(this.heading) * 1.2,
140:       );
141:     }
142:   }
143: 
144:   get radius() {
