257:   buildNeck({ bodyLen, bodyW, bodyH, bodyY, neckLen, accentColor }) {
258:     const g = this.genome;
259:     const neckGroup = new THREE.Group();
260:     neckGroup.position.set(0, bodyY + bodyH * 0.3, bodyLen * 0.69);
261:     neckGroup.rotation.x = 0.62 + g.neck * 0.2;
262:     this.model.add(neckGroup);
263:     this.neckGroup = neckGroup;
264: 
265:     const segCount = 4;
266:     for (let i = 0; i < segCount; i += 1) {
267:       const t = (i + 0.5) / segCount;
268:       const taper = 1 - t * 0.22;
269:       const segment = new THREE.Mesh(this.torsoGeo, this.bodyMat);
270:       const segLen = neckLen / segCount;
271:       segment.scale.set(
272:         (0.14 + g.neck * 0.022) * taper,
273:         segLen * 0.68,
274:         (0.135 + g.neck * 0.02) * taper,
275:       );
276:       segment.position.set(0, t * neckLen, Math.sin(t * Math.PI) * 0.035);
277:       segment.castShadow = true;
278:       neckGroup.add(segment);
279:     }
280: 
281:     const headGroup = new THREE.Group();
282:     headGroup.position.set(0, neckLen + 0.045, 0.085);
283:     headGroup.rotation.x = -0.54;
284:     neckGroup.add(headGroup);
285:     this.headGroup = headGroup;
286: 
287:     const headR = 0.205 + g.crest * 0.026;
288:     const cranium = new THREE.Mesh(this.torsoGeo, this.bodyMat);
289:     cranium.scale.set(headR * 1.02, headR * 0.9, headR * 1.28);
290:     cranium.castShadow = true;
291:     headGroup.add(cranium);
292: 
293:     const snout = new THREE.Mesh(this.torsoGeo, this.bodyMat);
294:     snout.scale.set(headR * 0.72, headR * 0.5, headR * 1.05);
295:     snout.position.set(0, -headR * 0.17, headR * 1.48);
296:     snout.castShadow = true;
297:     headGroup.add(snout);
298: 
299:     const jaw = new THREE.Mesh(this.torsoGeo, this.bellyMat);
300:     jaw.scale.set(headR * 0.62, headR * 0.24, headR * 0.88);
301:     jaw.position.set(0, -headR * 0.55, headR * 1.36);
302:     headGroup.add(jaw);
303: 
304:     const browRidge = new THREE.Mesh(this.torsoGeo, this.limbMat);
305:     browRidge.scale.set(headR * 0.84, headR * 0.18, headR * 0.52);
306:     browRidge.position.set(0, headR * 0.5, headR * 0.36);
307:     headGroup.add(browRidge);
308: 
309:     for (const side of [-1, 1]) {
310:       const eyeSocket = new THREE.Mesh(this.torsoGeo, this.bellyMat);
311:       eyeSocket.scale.set(headR * 0.35, headR * 0.3, headR * 0.32);
312:       eyeSocket.position.set(side * headR * 0.78, headR * 0.25, headR * 0.62);
313:       headGroup.add(eyeSocket);
