357:     // Neck frill when display alleles are strong.
358:     if (g.crest > 0.64) {
359:       for (const side of [-1, 1]) {
360:         const frill = new THREE.Mesh(new THREE.ConeGeometry(0.028, 0.16, 4), this.accentMat);
361:         frill.position.set(side * 0.095, neckLen * 0.72, 0);
362:         frill.rotation.z = side * 1.15;
363:         neckGroup.add(frill);
