404:   buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
405:     const g = this.genome;
406:     const upperLen = legLen * 0.55;
407:     const lowerLen = legLen * 0.48;
408:     const legRadius = 0.058 + g.bodySize * 0.032;
409:     const positions = [
410:       { x: -bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: 0 },
411:       { x: bodyW * 0.82, z: bodyLen * 0.47, front: true, phase: Math.PI },
412:       { x: -bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: Math.PI },
413:       { x: bodyW * 0.75, z: -bodyLen * 0.5, front: false, phase: 0 },
414:     ];
415: 
416:     positions.forEach((entry, i) => {
417:       const root = new THREE.Group();
418:       root.position.set(entry.x, bodyY - bodyH * 0.26, entry.z);
419:       this.model.add(root);
420: 
421:       const shoulder = new THREE.Mesh(this.torsoGeo, this.limbMat);
422:       shoulder.scale.set(legRadius * 1.22, legRadius * 1.25, legRadius * 1.3);
423:       root.add(shoulder);
424: 
425:       const thigh = new THREE.Mesh(this.torsoGeo, this.limbMat);
426:       thigh.scale.set(legRadius * 1.35, upperLen * 0.32, legRadius * 1.35);
427:       thigh.position.y = -upperLen * 0.36;
428:       thigh.castShadow = true;
429:       root.add(thigh);
430: 
431:       const upper = new THREE.Mesh(
432:         new THREE.CylinderGeometry(legRadius * 0.82, legRadius * 0.68, upperLen, 8),
433:         this.limbMat,
434:       );
435:       upper.position.y = -upperLen / 2;
436:       upper.castShadow = true;
437:       root.add(upper);
438: 
439:       const knee = new THREE.Group();
440:       knee.position.y = -upperLen;
441:       root.add(knee);
442: 
443:       const kneeJoint = new THREE.Mesh(this.torsoGeo, this.limbMat);
444:       kneeJoint.scale.setScalar(legRadius * 0.8);
445:       knee.add(kneeJoint);
446: 
447:       const lower = new THREE.Mesh(
448:         new THREE.CylinderGeometry(legRadius * 0.68, legRadius * 0.5, lowerLen, 7),
449:         this.limbMat,
450:       );
451:       lower.position.y = -lowerLen / 2;
452:       lower.castShadow = true;
453:       knee.add(lower);
454: 
455:       const foot = new THREE.Mesh(this.torsoGeo, this.limbMat);
456:       foot.scale.set(legRadius * 1.65, legRadius * 0.58, legRadius * 2.25);
457:       foot.position.set(0, -lowerLen - legRadius * 0.17, legRadius * 0.7);
458:       foot.castShadow = true;
459:       knee.add(foot);
460: 
461:       for (let toe = -1; toe <= 1; toe += 1) {
462:         const claw = new THREE.Mesh(new THREE.ConeGeometry(legRadius * 0.17, legRadius * 0.75, 4), this.darkBoneMat);
463:         claw.position.set(toe * legRadius * 0.62, -lowerLen + legRadius * 0.02, legRadius * 1.9);
464:         claw.rotation.x = Math.PI / 2.4;
465:         knee.add(claw);
466:       }
467: 
468:       this.legs.push({
469:         root,
470:         knee,
471:         phase: entry.phase,
472:         front: entry.front,
473:         upperLen,
474:         lowerLen,
475:         baseRot: entry.front ? 0.05 : -0.04,
476:       });
477:     });
478:   }
479: 
480:   buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen }) {
481:     const g = this.genome;
482:     if (g.armor < 0.22) return;
483:     const count = 3 + Math.round(g.armor * 5);
484:     for (let i = 0; i < count; i += 1) {
485:       const t = (i / (count - 1 || 1)) * 1.5 - 0.75;
486:       const z = t * bodyLen * 0.76;
487:       const profile = Math.sqrt(Math.max(0.06, 1 - Math.pow(t * 0.72, 2)));
488:       const height = (0.11 + g.armor * 0.26) * (0.7 + profile * 0.55);
489:       const spike = new THREE.Mesh(new THREE.ConeGeometry(0.045 + g.armor * 0.026, height, 4), this.boneMat);
490:       spike.position.set(0, bodyY + bodyH * profile * 0.93, z);
491:       spike.rotation.x = -0.34 - g.armor * 0.18;
492:       spike.rotation.y = Math.PI / 4;
493:       spike.castShadow = true;
494:       this.model.add(spike);
495:     }
496: 
497:     if (g.armor > 0.62) {
498:       for (const side of [-1, 1]) {
499:         const plate = new THREE.Mesh(new THREE.ConeGeometry(0.11, 0.18, 4), this.boneMat);
500:         plate.position.set(side * bodyW * 0.55, bodyY + bodyH * 0.5, bodyLen * 0.55);
501:         plate.rotation.z = side * 0.6;
502:         plate.rotation.x = -0.3;
503:         plate.castShadow = true;
504:         this.model.add(plate);
505:       }
506:     }
507:   }
508: 
509:   buildAccents({ bodyLen, bodyW, bodyH, bodyY }) {
510:     const g = this.genome;
511:     const spotCount = Math.round(1 + g.pattern * 5);
512:     for (let i = 0; i < spotCount; i += 1) {
513:       const side = i % 2 === 0 ? -1 : 1;
514:       const t = (i / Math.max(1, spotCount - 1)) * 1.4 - 0.7;
515:       const spot = new THREE.Mesh(new THREE.SphereGeometry(0.008 + g.pattern * 0.012, 6, 5), this.spotMat);
516:       spot.position.set(side * bodyW * 0.98, bodyY - bodyH * 0.05 + Math.sin(t * 3) * 0.03, t * bodyLen * 0.68);
517:       this.model.add(spot);
518:     }
519:   }
520: 
521:   chooseTarget(initial = false) {
522:     const angle = this.rng() * TAU;
523:     const dist = initial ? 0 : (this.index === 0 ? 0.8 : 1.1) + this.rng() * (this.index === 0 ? 1.7 : 2.2);
524:     let x = this.home.x + Math.cos(angle) * dist;
525:     let z = this.home.z + Math.sin(angle) * dist;
526: 
527:     if (Math.hypot(x - POND.x, z - POND.z) < POND.radius + 0.8) {
528:       x = this.home.x - Math.cos(angle) * dist;
529:       z = this.home.z - Math.sin(angle) * dist;
530:     }
531:     const r = Math.hypot(x, z);
532:     if (r > 7.1) {
533:       x *= 7.1 / r;
534:       z *= 7.1 / r;
535:     }
536:     this.target.set(x, 0, z);
537:   }
538: 
539:   update(dt) {
540:     const elapsed = this.world.time - this.spawnTime;
541:     const spawnT = clamp01(elapsed / 0.8);
542:     this.model.scale.setScalar(this.sizeScale * Math.max(0.01, easeOutBack(spawnT)));
543:     this.model.visible = spawnT > 0;
544:     if (spawnT < 1) {
545:       this.model.rotation.z = Math.sin(spawnT * Math.PI) * 0.04;
546:       return;
547:     }
548:     this.model.rotation.z *= 0.9;
549: 
550:     const speedGene = 0.6 + this.genome.speed * 1.45;
