362: function drawChart() {
363:   const canvas = els.chart;
364:   const ctx = canvas.getContext("2d");
365:   const width = canvas.width;
366:   const height = canvas.height;
367:   ctx.clearRect(0, 0, width, height);
368: 
369:   const values = state.history.slice(-20);
370:   const min = 28;
371:   const max = 96;
372:   const padX = 5;
373:   const padY = 13;
374: 
375:   ctx.save();
376:   ctx.strokeStyle = "rgba(180, 255, 220, 0.08)";
377:   ctx.lineWidth = 1;
378:   ctx.setLineDash([3, 7]);
379:   for (let i = 0; i < 4; i += 1) {
380:     const y = padY + ((height - padY * 2) / 3) * i;
381:     ctx.beginPath();
382:     ctx.moveTo(0, y);
383:     ctx.lineTo(width, y);
384:     ctx.stroke();
385:   }
386:   ctx.restore();
387: 
388:   if (!values.length) return;
389: 
390:   const graphValues = values.length === 1 ? [values[0], values[0]] : values;
391:   const getY = (value) => padY + (1 - (clamp(value, min, max) - min) / (max - min)) * (height - padY * 2);
392:   const getX = (index) => padX + (index / (graphValues.length - 1)) * (width - padX * 2);
393: 
394:   const points = graphValues.map((value, index) => ({ x: getX(index), y: getY(value) }));
395: 
396:   ctx.beginPath();
397:   ctx.moveTo(points[0].x, height);
398:   ctx.lineTo(points[0].x, points[0].y);
399:   for (let i = 1; i < points.length; i += 1) {
400:     const prev = points[i - 1];
401:     const point = points[i];
402:     const midX = (prev.x + point.x) / 2;
403:     ctx.bezierCurveTo(midX, prev.y, midX, point.y, point.x, point.y);
404:   }
405:   ctx.lineTo(points[points.length - 1].x, height);
406:   ctx.closePath();
407:   const fill = ctx.createLinearGradient(0, 0, 0, height);
408:   fill.addColorStop(0, "rgba(201, 255, 102, 0.2)");
409:   fill.addColorStop(1, "rgba(201, 255, 102, 0)");
410:   ctx.fillStyle = fill;
411:   ctx.fill();
412: 
413:   ctx.beginPath();
414:   ctx.moveTo(points[0].x, points[0].y);
415:   for (let i = 1; i < points.length; i += 1) {
416:     const prev = points[i - 1];
417:     const point = points[i];
418:     const midX = (prev.x + point.x) / 2;
419:     ctx.bezierCurveTo(midX, prev.y, midX, point.y, point.x, point.y);
420:   }
421:   const stroke = ctx.createLinearGradient(0, 0, width, 0);
422:   stroke.addColorStop(0, "#58f0c0");
423:   stroke.addColorStop(1, "#caff72");
424:   ctx.strokeStyle = stroke;
425:   ctx.lineWidth = 3;
426:   ctx.shadowColor = "rgba(140, 255, 164, 0.48)";
427:   ctx.shadowBlur = 10;
428:   ctx.stroke();
429:   ctx.shadowBlur = 0;
430: 
431:   const last = points[points.length - 1];
432:   ctx.beginPath();
433:   ctx.arc(last.x, last.y, 6.5, 0, Math.PI * 2);
434:   ctx.fillStyle = "rgba(202, 255, 114, 0.18)";
435:   ctx.fill();
436:   ctx.beginPath();
437:   ctx.arc(last.x, last.y, 3.2, 0, Math.PI * 2);
438:   ctx.fillStyle = "#d8ff86";
439:   ctx.fill();
440: 
441:   const previous = values.length > 1 ? values[values.length - 2] : values[values.length - 1];
442:   const delta = (values[values.length - 1] || 0) - previous;
443:   els.chartDelta.textContent = `${delta >= 0 ? "+" : "−"}${Math.abs(delta).toFixed(1)}`;
444:   els.chartDelta.style.color = delta >= 0 ? "var(--mint)" : "var(--coral)";
445: }
