615:   buildTrees(group, rng) {
616:     const trunkMat = new THREE.MeshStandardMaterial({ color: 0x3c3b2d, roughness: 0.97, flatShading: true });
617:     const canopyMats = [
618:       new THREE.MeshStandardMaterial({ color: 0x264735, roughness: 0.85, flatShading: true }),
619:       new THREE.MeshStandardMaterial({ color: 0x31543a, roughness: 0.88, flatShading: true }),
620:       new THREE.MeshStandardMaterial({ color: 0x1e3c30, roughness: 0.9, flatShading: true }),
621:     ];
622:     const positions = [
623:       [-7.6, -6.6, 3.5],
624:       [-2.6, -8.6, 2.8],
625:       [5.6, -7.7, 3.9],
626:       [8.1, -3.2, 2.7],
627:       [-8.9, 1.2, 2.5],
628:     ];
629: 
630:     positions.forEach(([x, z, height], index) => {
631:       const tree = new THREE.Group();
632:       tree.position.set(x, terrainHeight(x, z), z);
633:       tree.rotation.y = rng() * Math.PI * 2;
634:       const trunkHeight = height * 0.66;
635:       const trunk = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.2, trunkHeight, 7), trunkMat);
636:       trunk.position.y = trunkHeight / 2;
637:       trunk.rotation.z = (rng() - 0.5) * 0.28;
638:       trunk.castShadow = true;
639:       tree.add(trunk);
640: 
641:       for (let b = 0; b < 2; b += 1) {
642:         const branch = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.08, trunkHeight * 0.45, 5), trunkMat);
643:         branch.position.set((rng() - 0.5) * 0.55, trunkHeight * (0.56 + b * 0.1), (rng() - 0.5) * 0.4);
644:         branch.rotation.z = (rng() - 0.5) * 1.4;
645:         branch.rotation.x = (rng() - 0.5) * 0.9;
646:         tree.add(branch);
