910:     const group = new THREE.Group();
911:     group.position.set(position.x, terrainHeight(position.x, position.z) + 0.3, position.z);
912:     const particles = [];
913:     for (let i = 0; i < 18; i += 1) {
914:       const mat = new THREE.MeshBasicMaterial({
915:         color,
916:         transparent: true,
917:         opacity: 0.92,
918:         blending: THREE.AdditiveBlending,
919:         depthWrite: false,
920:       });
921:       const mesh = new THREE.Mesh(new THREE.SphereGeometry(0.016 + Math.random() * 0.024, 5, 4), mat);
922:       mesh.position.set((Math.random() - 0.5) * 0.3, Math.random() * 0.1, (Math.random() - 0.5) * 0.3);
923:       group.add(mesh);
924:       const angle = Math.random() * Math.PI * 2;
925:       const speed = 0.65 + Math.random() * 1.3;
926:       particles.push({
927:         mesh,
928:         vx: Math.cos(angle) * speed,
929:         vz: Math.sin(angle) * speed,
930:         vy: 0.8 + Math.random() * 1.6,
931:         life: 0.9 + Math.random() * 0.55,
932:       });
933:     }
934:     group.scale.setScalar(scale);
935:     this.scene.add(group);
936:     this.bursts.push({ group, particles, age: 0, duration: 1.35 });
937:   }
