252:     this.buildLegs({ bodyLen, bodyW, bodyH, bodyY, legLen });
253:     this.buildArmor({ bodyLen, bodyW, bodyH, bodyY, legLen });
254:     this.buildAccents({ bodyLen, bodyW, bodyH, bodyY });
