459: function pickDominantPressure(org) {
460:   const weights = org.evaluation.weights;
461:   const entries = Object.entries(weights).sort((a, b) => b[1] - a[1]);
462:   const labels = {
463:     thermal: "thermoregulation",
464:     foraging: "forage access",
465:     defense: "predator defense",
466:     efficiency: "metabolic efficiency",
467:   };
468:   return labels[entries[0][0]];
469: }
