834: function gameLoop(now) {
835:   const rawDt = Math.min(1, (now - (gameLoop.last || now)) / 1000);
836:   const dt = Math.min(0.05, rawDt);
837:   gameLoop.last = now;
838:   creatures.update(dt);
839:   updateCreatureTag();
