  await new Promise((ok,fail)=>{ws.onopen=ok;ws.onerror=fail});
  let id=0; const pending=new Map(); const errors=[];
  ws.onmessage=e=>{const m=JSON.parse(e.data);if(m.id&&pending.has(m.id)){pending.get(m.id)(m);pending.delete(m.id)}else if(m.method==='Runtime.exceptionThrown') errors.push(m.params.exceptionDetails.text);else if(m.method==='Runtime.consoleAPICalled'&&m.params.type==='error') errors.push(m.params.args.map(a=>a.value||a.description).join(' '))};
  const send=(method,params={})=>new Promise(resolve=>{const n=++id;pending.set(n,resolve);ws.send(JSON.stringify({id:n,method,params}))});
  const ev=async expression=>(await send('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result?.result?.value;
  await send('Page.enable'); await send('Runtime.enable'); await send('Log.enable');
  await send('Page.navigate',{url:'http://127.0.0.1:4173/'});
  for(let i=0;i<60;i++){await new Promise(r=>setTimeout(r,500));if(await ev('Boolean(window.__helix)'))break;}
  const initial=await ev(`({generation:document.querySelector('#stat-generation').textContent,population:document.querySelector('#stat-population').textContent,fitness:document.querySelector('#stat-fitness').textContent,canvas:!!document.querySelector('#scene').getContext('webgl2')})`);
  await ev(`document.querySelector('#climate-control [data-value="0"]').click()`);
  const climate=await ev(`document.querySelector('#climate-readout').textContent`);
  await ev(`document.querySelector('#btn-mutate').click()`);
  const afterMutation=await ev(`({mutagen:document.querySelectorAll('#mutagen-pips i.full').length,fitness:document.querySelector('#specimen-fitness').textContent})`);
  await ev(`document.querySelector('#btn-evolve').click()`);
  await new Promise(r=>setTimeout(r,500));
  const afterEvolve=await ev(`({generation:document.querySelector('#stat-generation').textContent,population:document.querySelector('#stat-population').textContent,chartEnd:document.querySelector('#chart-end').textContent,selection:document.querySelectorAll('#pop-dots .active').length})`);
  await ev(`document.querySelector('#btn-help').click()`);
  const help=await ev(`document.querySelector('#help-modal').classList.contains('open')`);
  await ev(`document.querySelector('#btn-help-close').click()`);
  await ev(`document.querySelector('#btn-auto').click()`);
  const auto=await ev(`document.querySelector('#auto-label').textContent`);
  console.log(JSON.stringify({initial,climate,afterMutation,afterEvolve,help,auto,errors},null,2));
  ws.close();
}
EOF

